import sys

def totalMinutes(hours, minutes):
    return hours * 60 + minutes

def main():
    data = sys.stdin.read().strip().split()
    if len(data) < 2:
        return
    hours = int(data[0])
    minutes = int(data[1])
    print(totalMinutes(hours, minutes))

if __name__ == "__main__":
    main()
